   pub struct TxIngressChannel {
       pub sender: tokio::sync::mpsc::Sender<SignedTx>,
       pub receiver: tokio::sync::Mutex<tokio::sync::mpsc::Receiver<SignedTx>>,
   }
   impl TxIngressChannel {
       pub fn new(cap: usize) -> Self { ... }
   }
   Добавить поле в App: pub(crate) tx_ingress: Arc<TxIngressChannel>

4. Правка handlers_tx.rs — горячий путь (non-roaming ветка, ~строки 229–260):
   БЫЛО:
     let mut g = a.inner.write().await;
     // ... precheck ...
     g.pool.push(tx).map_err(|_| (507, 'mempool is full'))?;
     drop(g);
   СТАЛО:
     // краткий read lock только для precheck
     {
         let g = a.inner.read().await;
         let (next_h, next_ts) = g.chain.next_apply_ctx()...?;
         g.chain.st.precheck_apply_with_ctx(&tx, next_h, next_ts, &g.chain.cfg)
             .map_err(|e| tx_tip_precheck_err(&tx, e))?;
     } // read lock дропается здесь
     // push в канал без lock
     a.tx_ingress.sender.try_send(tx.clone()).map_err(|_| {
         (StatusCode::INSUFFICIENT_STORAGE, 'mempool is full'.to_string())
     })?;
     // логировать accepted
   ВАЖНО: roaming ветки (Export/Import/ClaimIPv4Batch) не трогать — они используют g.chain.seal напрямую и требуют write lock.

5. Правка lifecycle.rs — seal loop, перед pool.take:
   НАЙТИ строку: let txs = g.pool.take(64);
   ДОБАВИТЬ ПЕРЕД НЕЙ:
     // drain ingress channel into local mempool под write lock
     if let Ok(rx) = app.tx_ingress.receiver.try_lock() {
         while let Ok(tx) = rx.try_recv() {
             let _ = g.pool.push(tx);
         }
     }
   app здесь — переменная типа App (или &App), доступная в seal loop.
